mockup.css:
.mock-section-collage-overlap { background: #e8e3d7; color: #1a1710; font-family: var(--f-sans); }
.mock-section-collage-overlap i { position: absolute; display: block; box-shadow: 0 1.2cqw 3cqw rgba(20,15,8,.24); }
.mock-section-collage-overlap .c1 { left: 4%; top: 11%; inline-size: 38%; block-size: 66%; }
.mock-section-collage-overlap .c2 { left: 30%; top: 29%; inline-size: 32%; block-size: 62%; z-index: 2; }
.mock-section-collage-overlap .c3 { left: 55%; top: 6%; inline-size: 30%; block-size: 50%; }
.mock-section-collage-overlap .cap { position: absolute; right: 5cqw; bottom: 6cqw; inline-size: 26cqw;
  text-align: end; display: flex; flex-direction: column; gap: .8cqw; }
.mock-section-collage-overlap .cap b { font-family: var(--f-serif); font-weight: 400; font-size: 3cqw; line-height: 1.1; }
.mock-section-collage-overlap .cap span { font-family: var(--f-mono); font-size: 1.15cqw;
  letter-spacing: .14em; text-transform: uppercase; opacity: .5; }
